/// An immediately-invoked closure *literal* (never bound to a `let`,
/// so its environment is a fresh construction, not a borrowed read) must
/// still call through correctly and release its environment -- guards
/// `Codegen::emit_closure_call`'s release, which used to be skipped
/// entirely for exactly this case.
#[test]
fn runtime_immediately_invoked_fresh_closure_literal_end_to_end() {
    let src = "fn main():\n    let x = 10\n    let r = (fn(y: i32) -> i32: x + y)(5)\n    println(f\"{r}\")\n";
    let output = compile_and_run("iife_fresh_closure", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "15");
}

// ===== inline if-expressions ================================================

/// The language reference's inline `if`-expression form -- `let result =
/// if x > 0: "pos" else: "neg"`, both arms on the same line -- must parse.
/// Previously `Parser::parse_if_expr` unconditionally demanded an indented
/// block after each `:`, so the documented one-liner failed with "expected
/// end of line".
#[test]
fn parses_inline_if_expression() {
    let src = "fn main():\n    let v = if 3 > 2: 10 else: 20\n";
    let module = Driver::parse(src).expect("inline if-expression should parse");
    let Item::Fn(f) = &module.items[0] else { panic!("expected fn") };
    let Stmt::Let { value, .. } = &f.body.stmts[0] else { panic!("expected let") };
    assert!(matches!(value, Expr::If { .. }), "{:?}", value);
}

/// Inline `if`-expression arms evaluate to the right values end to end,
/// including one nested inside an f-string hole.
#[test]
fn runtime_inline_if_expression_end_to_end() {
    let src = concat!(
        "fn main():\n",
        "    let v = if 3 > 2: 10 else: 20\n",
        "    let w = if 3 < 2: 10 else: 20\n",
        "    let s = if v < w: \"lt\" else: \"ge\"\n",
        "    println(f\"{v} {w} {s} {if 1 < 2: 7 else: 8}\")\n",
    );
    let output = compile_and_run("inline_if_expression", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "10 20 lt 7");
}

/// An inline `then` arm may still pair with an indented-block `else` arm --
/// the two arms decide their form independently.
#[test]
fn parses_inline_then_arm_with_block_else_arm() {
    let src = "fn main():\n    let v = if 3 > 2: 10 else:\n        20\n    let w = v\n";
    Driver::parse(src).expect("mixed inline/block if-expression arms should parse");
}

// ===== chained tuple indexing ===============================================

/// `t.0.1` -- a tuple index chained on another tuple index -- must lex as
/// two integer indexes, not fold `0.1` into a float literal. The lexer now
/// suppresses float-fraction folding for a number that immediately follows
/// a member-access `.` (Star has no leading-dot `.5` float spelling, so no
/// real float literal can begin there).
#[test]
fn parses_chained_tuple_index() {
    let src = "fn main():\n    let t = ((1, 2), (3, 4))\n    let x = t.0.1\n";
    let module = Driver::parse(src).expect("chained tuple index should parse");
    let Item::Fn(f) = &module.items[0] else { panic!("expected fn") };
    let Stmt::Let { value, .. } = &f.body.stmts[1] else { panic!("expected let") };
    let Expr::TupleIndex { base, index: 1, .. } = value else { panic!("expected outer .1: {:?}", value) };
    assert!(matches!(base.as_ref(), Expr::TupleIndex { index: 0, .. }), "{:?}", base);
}

/// Chained tuple indexing reads the right elements end to end, three levels
/// deep -- and ordinary float literals (which share the `digits.digits`
/// shape the lexer fix discriminates on) still work right next to it.
#[test]
fn runtime_chained_tuple_index_end_to_end() {
    let src = concat!(
        "fn main():\n",
        "    let pair = ((1, (2, 3)), 4)\n",
        "    let f = 0.5\n",
        "    println(f\"{pair.0.1.0} {pair.0.1.1} {pair.1} {f + 0.25}\")\n",
    );
    let output = compile_and_run("chained_tuple_index", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "2 3 4 0.750000");
}

// ===== named constructor arguments and field defaults =======================

/// Named struct-literal arguments match their *named* field, in any order.
/// Previously the parser dropped the names outright and matched every
/// argument positionally, so `Pair(b = 1, a = 2)` silently compiled to
/// `a = 1, b = 2` -- a wrong-values miscompile with no diagnostic.
#[test]
fn runtime_named_struct_args_reorder_end_to_end() {
    let src = concat!(
        "struct Pair:\n    a: i32\n    b: i32\n",
        "fn main():\n",
        "    let p = Pair(b = 1, a = 2)\n",
        "    println(f\"{p.a} {p.b}\")\n",
    );
    let output = compile_and_run("named_struct_args_reorder", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "2 1");
}

/// A field omitted from a construction falls back to its declared default:
/// all-defaults `Config()`, one named override, and a positional prefix
/// (which fills fields in declaration order) with defaults completing the
/// rest. Previously field defaults were parsed but never applied anywhere.
#[test]
fn runtime_struct_field_defaults_end_to_end() {
    let src = concat!(
        "struct Config:\n    width: i32 = 640\n    height: i32 = 480\n    title: str = \"game\"\n",
        "fn main():\n",
        "    let c0 = Config()\n",
        "    let c1 = Config(height = 720)\n",
        "    let c2 = Config(800, title = \"demo\")\n",
        "    println(f\"{c0.width} {c0.height} {c0.title}\")\n",
        "    println(f\"{c1.width} {c1.height} {c1.title}\")\n",
        "    println(f\"{c2.width} {c2.height} {c2.title}\")\n",
    );
    let output = compile_and_run("struct_field_defaults", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["640 480 game", "640 720 game", "800 480 demo"], "{}", stdout);
}

/// Named arguments and defaults work through the generic-struct
/// monomorphization path too (resolution happens at the AST level, before
/// type-parameter unification, so a reordered/omitted argument can't skew
/// the inferred type arguments).
#[test]
fn runtime_named_args_generic_struct_end_to_end() {
    let src = concat!(
        "struct BoxG<T>:\n    value: T\n    tag: i32 = 7\n",
        "fn main():\n",
        "    let a = BoxG(value = 5)\n",
        "    let b = BoxG<str>(tag = 9, value = \"hi\")\n",
        "    println(f\"{a.value} {a.tag} {b.value} {b.tag}\")\n",
    );
    let output = compile_and_run("named_args_generic_struct", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "5 7 hi 9");
}

/// Named arguments match an enum variant's payload fields by name too.
#[test]
fn runtime_named_args_enum_variant_end_to_end() {
    let src = concat!(
        "enum Msg:\n    Move(dx: i32, dy: i32)\n    Quit\n",
        "fn main():\n",
        "    let m = Msg::Move(dy = 3, dx = 4)\n",
        "    match m:\n",
        "        Msg::Move(dx, dy) -> println(f\"{dx} {dy}\")\n",
        "        Msg::Quit -> println(\"quit\")\n",
    );
    let output = compile_and_run("named_args_enum_variant", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "4 3");
}

/// `spawn` constructs the arena's element struct, so named arguments and
/// field defaults apply there exactly like an ordinary struct literal.
#[test]
fn runtime_spawn_named_args_with_defaults_end_to_end() {
    let src = concat!(
        "struct Thing:\n    hp: i32 = 100\n    tag: i32 = 5\n",
        "arena Things: Thing\n",
        "fn main():\n",
        "    spawn Things(tag = 9)\n",
        "    let r = GenRef<Thing>(0)\n",
        "    let t = r[0]\n",
        "    println(f\"{t.hp} {t.tag}\")\n",
    );
    let output = compile_and_run("spawn_named_args_defaults", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "100 9");
}

/// An unknown field name in a struct construction is a clean checker error.
#[test]
fn rejects_unknown_named_ctor_argument() {
    let src = "struct Pair:\n    a: i32\n    b: i32\nfn main():\n    let p = Pair(a = 1, c = 2)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("unknown field name should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("has no field `c`")), "{:?}", errs);
}

/// The same field given twice (positionally and then again by name) is a
/// clean checker error, not a silent overwrite.
#[test]
fn rejects_duplicate_named_ctor_argument() {
    let src = "struct Pair:\n    a: i32\n    b: i32\nfn main():\n    let p = Pair(1, a = 2)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("duplicate field should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("given more than once")), "{:?}", errs);
}

/// A positional argument after a named one is ambiguous (which field does
/// it fill?) and is rejected outright, mirroring Python's rule.
#[test]
fn rejects_positional_ctor_argument_after_named() {
    let src = "struct Pair:\n    a: i32\n    b: i32\nfn main():\n    let p = Pair(b = 1, 2)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("positional-after-named should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("positional argument after a named argument")), "{:?}", errs);
}

/// Omitting a field that has no declared default is a clean checker error
/// naming the missing field.
#[test]
fn rejects_named_ctor_call_missing_field_without_default() {
    let src = "struct Pair:\n    a: i32\n    b: i32\nfn main():\n    let p = Pair(a = 1)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("missing defaultless field should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("missing a value for field `b`")), "{:?}", errs);
}

/// A purely positional construction that undersupplies a struct with *no*
/// defaults keeps the original arity diagnostic (nothing about missing
/// fields or names).
#[test]
fn rejects_positional_ctor_undersupply_with_original_arity_error() {
    let src = "struct Pair:\n    a: i32\n    b: i32\nfn main():\n    let p = Pair(1)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("positional undersupply should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("expects 2 argument(s), found 1")), "{:?}", errs);
}

/// Ordinary function/method calls have no named-parameter machinery --
/// `name = expr` there is rejected instead of silently dropping the name
/// (which previously made `f(b = 1, a = 2)` *look* reordered while
/// matching purely positionally).
#[test]
fn rejects_named_arguments_on_ordinary_call() {
    let src = "fn add(a: i32, b: i32) -> i32:\n    a + b\nfn main():\n    let x = add(b = 1, a = 2)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("named args on a fn call should be rejected") };
    assert!(
        errs.iter().any(|d| d.message.contains("named arguments are only supported when constructing a struct or enum variant")),
        "{:?}",
        errs
    );
}

/// Builtin constructors (`Vec3`, `List`, ...) have no user-declared field
/// list to match names against, so named arguments there are rejected.
#[test]
fn rejects_named_arguments_on_builtin_constructor() {
    let src = "fn main():\n    let v = Vec3(x = 1.0, y = 2.0, z = 3.0)\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(errs) = Driver::check(&module) else { panic!("named args on Vec3(..) should be rejected") };
    assert!(errs.iter().any(|d| d.message.contains("named arguments are not supported")), "{:?}", errs);
}

/// All-named construction sites in declaration order -- the pre-existing
/// examples' style -- still work unchanged through the new resolution.
#[test]
fn runtime_named_args_in_declaration_order_end_to_end() {
    let src = concat!(
        "struct Player:\n    name: str\n    hp: i32\n",
        "fn main():\n",
        "    let p = Player(name = \"Hero\", hp = 100)\n",
        "    println(f\"{p.name} {p.hp}\")\n",
    );
    let output = compile_and_run("named_args_declaration_order", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "Hero 100");
}

// === `Bytes` (docs/design.md's "Text and bytes" section) ===================

/// `Bytes()` starts empty; `push`/`len`/`[i]` behave exactly like `List<u8>`
/// (`Ty::Bytes` reuses that codegen wholesale -- see `Ty::Bytes`'s doc
/// comment).
#[test]
fn runtime_bytes_construct_push_len_index_end_to_end() {
    let src = "fn main():\n    let mut b = Bytes()\n    println(f\"{b.len()}\")\n    \
               b.push(10 as u8)\n    b.push(20 as u8)\n    b.push(30 as u8)\n    \
               println(f\"{b.len()}\")\n    println(f\"{b[0]} {b[1]} {b[2]}\")\n";
    let output = compile_and_run("bytes_construct_push_len_index", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["0", "3", "10 20 30"], "{}", stdout);
}

/// `bytes[i] = v` writes through in place, and a `u8` value wider than one
/// byte (via `as u8`) truncates, matching `List<u8>`'s own element-store
/// convention.
#[test]
fn runtime_bytes_index_write_end_to_end() {
    let src = "fn main():\n    let mut b = Bytes()\n    b.push(1 as u8)\n    b.push(2 as u8)\n    \
               b[0] = 250 as u8\n    b[1] = 321 as u8\n    println(f\"{b[0]} {b[1]}\")\n";
    let output = compile_and_run("bytes_index_write", src);
    assert!(output.status.success(), "{:?}", output.status);
    // 321 truncated to u8 is 321 - 256 = 65.
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "250 65");
}

/// `pop()` removes the last-pushed byte, LIFO.
#[test]
fn runtime_bytes_pop_end_to_end() {
    let src = "fn main():\n    let mut b = Bytes()\n    b.push(1 as u8)\n    b.push(2 as u8)\n    b.push(3 as u8)\n    \
               println(f\"{b.pop()}\")\n    println(f\"{b.pop()}\")\n    println(f\"{b.len()}\")\n";
    let output = compile_and_run("bytes_pop", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["3", "2", "1"], "{}", stdout);
}

/// An out-of-bounds read/pop on an empty (never-pushed) `Bytes` yields `0`,
/// the element type's zero value -- the same "safe null equivalent"
/// convention `List<T>` uses, not a crash or trap.
#[test]
fn runtime_bytes_out_of_bounds_reads_are_safe_end_to_end() {
    let src = "fn main():\n    let mut b = Bytes()\n    println(f\"{b[0]}\")\n    println(f\"{b.pop()}\")\n    \
               b.push(9 as u8)\n    println(f\"{b[5]}\")\n";
    let output = compile_and_run("bytes_oob_safe", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["0", "0", "0"], "{}", stdout);
}

/// `let b = a` is an O(1) refcount bump sharing one buffer; mutating one
/// binding (`push`) must not be visible through the other -- the same
/// copy-on-write guarantee `List<T>` gives (`Ty::Bytes`'s doc comment: it
/// reuses that exact codegen).
#[test]
fn runtime_bytes_copy_on_write_end_to_end() {
    let src = "fn main():\n    let mut a = Bytes()\n    a.push(1 as u8)\n    a.push(2 as u8)\n    \
               let b = a\n    a.push(3 as u8)\n    println(f\"{a.len()} {b.len()}\")\n";
    let output = compile_and_run("bytes_cow", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "3 2");
}

/// `bytes_from_str`/`str_from_bytes` round-trip a `str`'s bytes exactly,
/// including the empty string (a real `malloc(0)`, not special-cased).
#[test]
fn runtime_bytes_from_str_round_trip_end_to_end() {
    let src = "fn main():\n    let b = bytes_from_str(\"Hi!\")\n    println(f\"{b.len()}\")\n    println(f\"{b[0]} {b[1]} {b[2]}\")\n    \
               println(str_from_bytes(b))\n    let empty = bytes_from_str(\"\")\n    println(f\"{empty.len()}\")\n    \
               println(f\"[{str_from_bytes(empty)}]\")\n";
    let output = compile_and_run("bytes_from_str_round_trip", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["3", "72 105 33", "Hi!", "0", "[]"], "{}", stdout);
}

/// `Bytes` is a nominally distinct type from `List<u8>`, even though they
/// share an identical runtime layout (mirrors `Handle<T>` vs. `GenRef<T>`).
#[test]
fn rejects_bytes_passed_where_list_u8_expected() {
    let src = "fn take(xs: List<u8>) -> i32:\n    xs.len()\nfn main():\n    let b = Bytes()\n    take(b)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("Bytes should not satisfy a List<u8> parameter");
    assert!(!diags.is_empty(), "{:?}", diags);
}

#[test]
fn rejects_bytes_constructor_with_arguments() {
    let src = "fn main():\n    let b = Bytes(1 as u8)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("Bytes() should take no arguments");
    assert!(diags.iter().any(|d| d.message.contains("takes no arguments")), "{:?}", diags);
}

/// `Bytes` has no structural-equality story (mirrors `List<T>`), so it can't
/// be used as a `Map`/`Set` key.
#[test]
fn rejects_bytes_used_as_map_key() {
    let src = "fn main():\n    let m: Map<Bytes, i32> = Map<Bytes, i32>()\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("Bytes should not be a legal Map key type");
    assert!(diags.iter().any(|d| d.message.contains("cannot be used as a `Map`/`Set` key")), "{:?}", diags);
}

/// Repeated push/pop churn well past the initial capacity doubles -- a
/// regression guard on `emit_bytes_from_str`/`ListMethod::Push`'s grow path
/// leaking the buffer it replaces every time it doubles.
#[test]
fn runtime_bytes_push_growth_does_not_leak_end_to_end() {
    let src = "fn main():\n    let mut b = Bytes()\n    let mut i: i32 = 0\n    let mut total: i32 = 0\n    \
               while i < 400000:\n        b.push((i as u8))\n        total = total + (b[b.len() - 1] as i32)\n        \
               if b.len() > 1000:\n            b.pop()\n        i += 1\n    println(\"done\")\n";
    assert_no_leak("bytes_push_growth_leak", src, 20 * 1024 * 1024);
}

// === `Symbol` (docs/design.md's "Text and bytes" section) ==================

/// Two `Symbol(..)` constructions of equal strings intern to the same id,
/// so `==` between them is `true` -- the core guarantee this type exists
/// for (`docs/design.md`: "comparing tags... every frame is a real cost").
#[test]
fn runtime_symbol_equal_strings_intern_to_same_id_end_to_end() {
    let src = "fn main():\n    let a = Symbol(\"player\")\n    let b = Symbol(\"player\")\n    println(f\"{a == b}\")\n";
    let output = compile_and_run("symbol_equal_strings_same_id", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "true");
}

/// Distinct strings intern to distinct ids.
#[test]
fn runtime_symbol_distinct_strings_differ_end_to_end() {
    let src = "fn main():\n    let a = Symbol(\"player\")\n    let b = Symbol(\"enemy\")\n    println(f\"{a == b}\")\n    println(f\"{a != b}\")\n";
    let output = compile_and_run("symbol_distinct_strings_differ", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["false", "true"], "{}", stdout);
}

/// `Symbol <-> i64` is a free bit-preserving relabel; interning order is
/// deterministic (first-seen order) within one run, so ids are stable.
#[test]
fn runtime_symbol_cast_round_trip_end_to_end() {
    let src = "fn main():\n    let a = Symbol(\"first\")\n    let b = Symbol(\"second\")\n    \
               let a_id = a as i64\n    let b_id = b as i64\n    println(f\"{a_id} {b_id}\")\n    \
               let back = b_id as Symbol\n    println(f\"{back == b}\")\n";
    let output = compile_and_run("symbol_cast_round_trip", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["0 1", "true"], "{}", stdout);
}

/// `symbol_name` reverses the interning lookup, returning the original
/// string -- and a fresh, independently-owned copy (a second call, or
/// releasing the caller's copy, must not corrupt the table's own entry).
#[test]
fn runtime_symbol_name_round_trip_end_to_end() {
    let src = "fn main():\n    let a = Symbol(\"hello world\")\n    println(symbol_name(a))\n    println(symbol_name(a))\n";
    let output = compile_and_run("symbol_name_round_trip", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["hello world", "hello world"], "{}", stdout);
}

/// A `Symbol` id that never came from `Symbol(..)` (here, an out-of-range
/// `as`-cast integer) is a safe out-of-bounds read rather than a crash:
/// `symbol_name` returns a real, freshly-allocated empty `str`.
///
/// Previously this returned `Codegen::zero_value(&Ty::Str)` -- a bare `null`
/// `i8*` -- instead of a real empty string, on the theory (this test used to
/// assert it directly) that it was "the same safe zero value `List<T>::pop`'s
/// empty-list case does" and therefore harmless; `println`'s f-string `%s`
/// hole happens to tolerate a null argument on this libc (rendering the
/// literal text `(null)`), which masked the actual problem. Confirmed as a
/// real, separate bug (not just a cosmetic one) via `runtime_symbol_name_out_
/// of_range_result_is_usable_as_a_real_string_end_to_end` below: passing that
/// same null "empty string" to `len(..)` (`strlen` on a null pointer)
/// segfaulted outright -- a null `str` is not actually interchangeable with
/// an empty one anywhere except that one lucky `printf` call. Fixed in
/// `Codegen::emit_symbol_name` (`src/codegen/symbol.rs`) by building a real
/// owned empty string (`star_rc_alloc` + a lone NUL byte, `env_get`'s
/// missing-variable convention) on the out-of-range path instead.
#[test]
fn runtime_symbol_name_out_of_range_returns_zero_value_end_to_end() {
    let src = "fn main():\n    let a = Symbol(\"only one\")\n    let bogus = (999999 as i64) as Symbol\n    println(f\"[{symbol_name(bogus)}]\")\n";
    let output = compile_and_run("symbol_name_out_of_range", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "[]");
}

/// Companion to `runtime_symbol_name_out_of_range_returns_zero_value_end_to_
/// end` above: an out-of-range `symbol_name` result must be a real,
/// independently-owned empty `str` any other string builtin can safely
/// operate on, not just something `println`'s f-string hole happens to
/// tolerate. Before the fix documented there, `len(..)` on this result
/// (`strlen` dereferencing a bare `null` `i8*`) segfaulted the whole
/// process.
#[test]
fn runtime_symbol_name_out_of_range_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let bogus = (999999 as i64) as Symbol\n    let n = symbol_name(bogus)\n    println(f\"{len(n)}\")\n";
    let output = compile_and_run("symbol_name_out_of_range_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// `List<str>::pop()` on an empty list is a safe out-of-bounds read rather
/// than a crash: it returns a real, freshly-allocated empty `str`.
///
/// Previously this returned `Codegen::zero_value(&Ty::Str)` -- a bare `null`
/// `i8*` -- exactly the same root cause `symbol_name`'s out-of-range fix
/// above addresses (see `runtime_symbol_name_out_of_range_returns_zero_value_
/// end_to_end`'s doc comment), just for `List<T>`'s own OOB/empty-pop
/// convention instead of `Symbol`'s. Confirmed as a real, separate segfault
/// (not just symbol.rs's already-fixed case) via a real `star build`+run of
/// `let mut l: List<str> = List<str>(); len(l.pop())` before this fix (`len`'s
/// `strlen` dereferencing the null "empty string" `pop` actually returned).
/// Fixed in `Codegen::zero_value_rc` (`src/codegen/mod.rs`), used by
/// `ListMethod::Pop`'s empty-list fallback (`src/codegen/list.rs`).
#[test]
fn runtime_list_pop_empty_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let mut l: List<str> = List<str>()\n    let s = l.pop()\n    println(f\"{len(s)}\")\n";
    let output = compile_and_run("list_pop_empty_str_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// Companion to `runtime_list_pop_empty_result_is_usable_as_a_real_string_end_
/// to_end` above, for `List<str>`'s other out-of-bounds-read path:
/// `list[idx]` past the end. Same fix (`Codegen::zero_value_rc`), same
/// `List<T>` module, different call site (`Codegen::emit_list_index`).
#[test]
fn runtime_list_index_out_of_bounds_str_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let l: List<str> = List<str>()\n    let s = l[5]\n    println(f\"{len(s)}\")\n";
    let output = compile_and_run("list_index_oob_str_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// `Ring<str,N>::pop()` on an empty ring is the same "safe zero-value read"
/// bug class as `List<str>::pop()` above (`Codegen::zero_value_rc`'s other
/// caller, `RingMethod::Pop` in `src/codegen/ring.rs`), confirmed via a real
/// segfault building and running `let mut r: Ring<str,4> = Ring<str,4>();
/// len(r.pop())` before this fix.
#[test]
fn runtime_ring_pop_empty_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let mut r: Ring<str, 4> = Ring<str, 4>()\n    let s = r.pop()\n    println(f\"{len(s)}\")\n";
    let output = compile_and_run("ring_pop_empty_str_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// Companion to `runtime_ring_pop_empty_result_is_usable_as_a_real_string_end_
/// to_end` above, for `Ring<str,N>`'s other out-of-bounds-read path:
/// `ring[idx]` past the current (dynamic) length. Same fix
/// (`Codegen::zero_value_rc`), different call site (`ring_index_ptr`).
#[test]
fn runtime_ring_index_out_of_bounds_str_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let r: Ring<str, 4> = Ring<str, 4>()\n    let s = r[2]\n    println(f\"{len(s)}\")\n";
    let output = compile_and_run("ring_index_oob_str_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// `[str; N]` (a fixed-size array) indexed out of bounds is the same "safe
/// zero-value read" bug class as `List<str>[idx]` above, just for
/// `crate::codegen::array`'s own `array_index_ptr` fallback -- confirmed via
/// a real segfault building and running `let a: [str; 3] = ["x"; 3];
/// len(a[99])` before this fix.
#[test]
fn runtime_array_index_out_of_bounds_str_result_is_usable_as_a_real_string_end_to_end() {
    let src = "fn main():\n    let a: [str; 3] = [\"x\"; 3]\n    let s = a[99]\n    println(f\"{len(s)}\")\n";
    let output = compile_and_run("array_index_oob_str_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "0");
}

/// `Table<T>::pop()` on an empty table, and `table[idx]` out of bounds, hand
/// back `T`'s zero value -- but `T` is always a struct (`Table<T>` requires
/// it), so `Codegen::zero_value`'s flat `zeroinitializer` would leave any
/// `str`-typed *field* of that zeroed struct as the same bare-null-disguised-
/// as-`str` hazard `List<str>::pop()` had, just one level of field-access
/// deeper. Confirmed via a real segfault building and running
/// `Table<Enemy>().pop()` (`Enemy` having a `name: str` field) then reading
/// `len(popped.name)`, and separately `Table<Enemy>()[99]` then
/// `len(oob.name)`, before this fix. Fixed in `Codegen::emit_table_index`'s
/// out-of-bounds branch and `TableMethod::Pop`'s empty branch
/// (`src/codegen/table.rs`), building the zero struct field-by-field via
/// `Codegen::zero_value_rc` instead of one flat `zero_value(ty)` store.
#[test]
fn runtime_table_pop_and_index_empty_struct_str_field_is_usable_as_a_real_string_end_to_end() {
    let src = "struct Enemy:\n    mut hp: i32\n    name: str\n\nfn main():\n    let mut t: Table<Enemy> = Table<Enemy>()\n    let popped = t.pop()\n    println(f\"{len(popped.name)}\")\n    let mut t2: Table<Enemy> = Table<Enemy>()\n    t2.push(Enemy(hp = 1, name = \"a\"))\n    let oob = t2[99]\n    println(f\"{len(oob.name)}\")\n";
    let output = compile_and_run("table_pop_and_index_empty_str_field_usable", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["0", "0"], "{}", stdout);
}

/// `Symbol` is a legal `Map`/`Set` key (`Checker::check_hashable_ty`) --
/// comparison is a single `i64` compare, so re-inserting an equal `Symbol`
/// overwrites rather than duplicating.
#[test]
fn runtime_symbol_as_map_key_end_to_end() {
    let src = "fn main():\n    let mut hp: Map<Symbol, i32> = Map<Symbol, i32>()\n    \
               hp.insert(Symbol(\"player\"), 100)\n    hp.insert(Symbol(\"enemy\"), 40)\n    hp.insert(Symbol(\"player\"), 80)\n    \
               println(f\"{hp.len()}\")\n    \
               match hp.get(Symbol(\"player\")):\n        Option::Some(v) -> println(f\"{v}\")\n        Option::None -> println(\"missing\")\n";
    let output = compile_and_run("symbol_as_map_key", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["2", "80"], "{}", stdout);
}

/// `Set<Symbol>` dedups equal-string `Symbol`s -- this is the regression
/// this section's `eq.rs` fix guards: before adding a dedicated
/// `Ty::Symbol` arm to `emit_eq_body`, its `_ => "true".into()` fallback
/// made every `Symbol` compare equal to every other one inside a
/// `Map`/`Set`, silently collapsing all keys/elements to one.
#[test]
fn runtime_symbol_as_set_key_dedups_end_to_end() {
    let src = "fn main():\n    let mut tags: Set<Symbol> = Set<Symbol>()\n    \
               tags.insert(Symbol(\"flying\"))\n    tags.insert(Symbol(\"flying\"))\n    tags.insert(Symbol(\"armored\"))\n    \
               println(f\"{tags.len()}\")\n    println(f\"{tags.contains(Symbol(\"flying\"))}\")\n    println(f\"{tags.contains(Symbol(\"stealth\"))}\")\n";
    let output = compile_and_run("symbol_as_set_key_dedups", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["2", "true", "false"], "{}", stdout);
}

#[test]
fn rejects_symbol_constructor_with_non_str_argument() {
    let src = "fn main():\n    let a = Symbol(1)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("Symbol(..) should require a str argument");
    assert!(diags.iter().any(|d| d.message.contains("expects 1 `str` argument")), "{:?}", diags);
}

/// Only `==`/`!=` are supported between `Symbol` values -- interning order
/// is an implementation detail, not a meaningful sort.
#[test]
fn rejects_symbol_ordering_comparison() {
    let src = "fn main():\n    let a = Symbol(\"a\")\n    let b = Symbol(\"b\")\n    let c = a < b\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("`<` between Symbols should be rejected");
    assert!(diags.iter().any(|d| d.message.contains("only `==`/`!=` are supported between `Symbol` values")), "{:?}", diags);
}

/// `Symbol` never implicitly mixes with a bare `i64` -- same "no implicit
/// anything" rule every other explicit-width/nominal type in this section
/// follows (an explicit `as` cast is always required).
#[test]
fn rejects_binop_between_symbol_and_bare_i64() {
    let src = "fn main():\n    let a = Symbol(\"a\")\n    let n: i64 = 0\n    let c = a == n\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("Symbol == i64 without a cast should be rejected");
    assert!(!diags.is_empty(), "{:?}", diags);
}

/// Repeatedly re-interning the *same* string exercises the "already
/// present" path (release-then-return-existing-id) in a loop -- a
/// regression guard on that path leaking the freshly-constructed `str`
/// argument instead of releasing it once its id is found.
#[test]
fn runtime_symbol_repeated_interning_of_same_string_does_not_leak_end_to_end() {
    let src = "fn main():\n    let mut i: i32 = 0\n    let mut total: i64 = 0 as i64\n    \
               while i < 400000:\n        let s = Symbol(\"same tag every time\")\n        total = total + (s as i64)\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("symbol_repeated_intern_leak", src, 20 * 1024 * 1024);
}

/// A closure literal lowers to its own independent top-level LLVM function
/// (see `Codegen::emit_closure_lit`), not an inline block of whatever
/// function it happens to be lexically written inside -- so a `break`/
/// `continue` in its body has no well-defined target even when the closure
/// literal sits lexically inside an enclosing `while`/`for` loop.
/// `Checker::loop_depth` was previously left untouched while checking a
/// closure body (unlike `Stmt::Par`'s body, which already resets it to `0`
/// for exactly this reason -- a `par`/`swarm` body also lowers to its own
/// separate function), so a closure defined inside a loop silently inherited
/// that loop's nonzero depth and a bare `break` directly in the closure's own
/// body type-checked cleanly. Confirmed via a real `star build` failure: the
/// closure still lowers to its own deferred `closure_N` function, but
/// codegen's `TypedStmt::Break` arm (which never needed to save/restore
/// `loop_stack` itself, since this checker gap was the only way a closure
/// body could ever contain a `break`/`continue` at all) emitted `br label
/// %while_end_3` -- a block label that only exists in the *enclosing*
/// `main` function -- and `clang` rejected the resulting IR with "use of
/// undefined value '%while_end_3'". Fixed by resetting `self.loop_depth` to
/// `0` around a closure body's type-checking, mirroring `Stmt::Par`'s own
/// `saved_loop_depth` handling.
#[test]
fn rejects_break_inside_closure_defined_in_loop() {
    let src = "fn main():\n    let mut i: i32 = 0\n    while i < 3:\n        let f = fn():\n            break\n        f()\n        i = i + 1\n    println(\"done\")\n";
    let module = Driver::parse(src).expect("should parse");
    let errs = Driver::check(&module)
        .expect_err("a bare `break` inside a closure body must be rejected even when the closure is lexically inside a loop");
    assert!(errs.iter().any(|d| d.message.contains("break") && d.message.contains("outside of a loop")), "{:?}", errs);
}

/// Same bug as above, `continue` instead of `break`.
#[test]
fn rejects_continue_inside_closure_defined_in_loop() {
    let src = "fn main():\n    let mut i: i32 = 0\n    while i < 3:\n        let f = fn():\n            continue\n        f()\n        i = i + 1\n    println(\"done\")\n";
    let module = Driver::parse(src).expect("should parse");
    let errs = Driver::check(&module)
        .expect_err("a bare `continue` inside a closure body must be rejected even when the closure is lexically inside a loop");
    assert!(errs.iter().any(|d| d.message.contains("continue") && d.message.contains("outside of a loop")), "{:?}", errs);
}

/// Companion control for the fix above: a closure with its *own* internal
/// loop must still be able to use `break`/`continue` normally inside that
/// loop -- only a `break`/`continue` with no loop of its own (only reachable
/// by inheriting an outer, lexically-enclosing loop's depth) is rejected.
/// Guards against an overly-blunt fix (e.g. unconditionally banning
/// `break`/`continue` anywhere inside a closure) breaking this legitimate case.
#[test]
fn runtime_closure_with_own_loop_break_still_works_end_to_end() {
    let src = "fn main():\n    let f = fn() -> i32:\n        let mut i: i32 = 0\n        while i < 10:\n            if i == 3:\n                break\n            i = i + 1\n        i\n    println(f\"{f()}\")\n";
    let output = compile_and_run("closure_own_loop_break", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(stdout.trim(), "3", "{}", stdout);
}

// =====================================================================
// ===== Bug-hunting round 2 (numeric types/casts/generics/Option/Result
// ===== audit): every fix below this marker was confirmed via a real
// ===== `star build`+run (an unbounded-working-set-growth reproduction for
// ===== the leaks, or direct stdout/exit-code inspection) before being
// ===== fixed, matching this file's existing convention. =================

/// `Codegen::contains_rc`/`emit_rc_walk` (`src/codegen/rc.rs`) had no arm
/// at all for `Ty::Enum` -- every payload enum (`Option<T>`, `Result<T,E>`,
/// or any user-defined enum with an RC-bearing variant field) silently fell
/// through `contains_rc`'s `_ => false` catch-all, so `Codegen::track_owned`
/// never registered an `Option<str>`/`Result<str,E>` local for release at
/// its scope's exit: a `let o = Option::Some(some_str)` that's never
/// explicitly matched/unwrapped leaked its payload's RC content on every
/// single evaluation. Confirmed via real unbounded working-set growth
/// (~83MB -> 390MB+ within 2 seconds of 30,000,000 iterations of `let o =
/// make_some(f"item{i}")`, flat on an otherwise-identical control with the
/// `Option<str>` wrapper removed) before this fix. Fixed by adding a
/// `Ty::Enum` arm to both functions: `contains_rc` is true whenever *any*
/// variant of the enum carries an RC-bearing field (the active variant is
/// only known at runtime); `emit_rc_walk` loads the runtime tag and
/// branches per RC-bearing variant, bitcasting the shared `[W x i64]`
/// payload buffer to that variant's own field layout exactly the way
/// `TypedExpr::EnumVariant` construction and `Pattern::EnumVariant`
/// destructuring already do, then recursing into each RC-bearing field.
#[test]
fn runtime_option_some_local_never_matched_does_not_leak_end_to_end() {
    let src = "fn make_some(s: str) -> Option<str>:\n    return Option::Some(s)\n\n\
               fn main():\n    let mut i: i32 = 0\n    \
               while i < 400000:\n        let o = make_some(concat(\"item\", \"x\"))\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("option_some_never_matched_leak", src, 20 * 1024 * 1024);
}

/// Same fix, exercised through a nested generic: `Option<Box<T>>` where
/// `Box<T>` is a plain user struct wrapping `T` -- `contains_rc(Ty::Enum)`
/// must recurse into a variant's field types via the ordinary `contains_rc`
/// walk (already correct for `Ty::Named`/struct fields), not just handle a
/// directly RC-bearing payload type like `str` itself.
#[test]
fn runtime_option_of_struct_wrapping_str_never_matched_does_not_leak_end_to_end() {
    let src = "struct Box<T>:\n    value: T\n\n\
               fn make(s: str) -> Option<Box<str>>:\n    return Option::Some(Box(value = s))\n\n\
               fn main():\n    let mut i: i32 = 0\n    \
               while i < 400000:\n        let b = make(concat(\"item\", \"x\"))\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("option_of_boxed_str_never_matched_leak", src, 20 * 1024 * 1024);
}

/// A `match` over a *fresh* (non-place) payload-enum scrutinee -- a function
/// call result, not an `Ident`/`Field`/other real storage --
/// `TypedExpr::Match`'s codegen (`src/codegen/expr.rs`) addresses such a
/// scrutinee via `Codegen::emit_place`, whose generic fallback spills the
/// already-owned call result into a scratch alloca. Every arm that binds
/// and reads a payload field (`Result::Ok(v) -> v`) reads that binding as
/// an ordinary `Ident`, which retains its own independent duplicate on
/// every use -- but the scrutinee's *own* reference needs the fallback's
/// spilled temporary to be tracked for release, exactly like any other
/// RC-bearing value spilled through that path (see `Codegen::emit_place`'s
/// generic-fallback doc comment in `src/codegen/mod.rs`, generalized in the
/// same bug-hunting round to track *every* RC-bearing type, not just
/// `List`/`Map`/`Set`/`Table` -- which already covers this scrutinee case
/// without a dedicated call site of its own). Confirmed via real unbounded
/// working-set growth (~40MB -> 270MB+ within 3 seconds of 30,000,000
/// iterations) on a hand-written `match Result::Ok(v)/Err(e) -> v/e` with no
/// `?` involved, before that generalization landed.
#[test]
fn runtime_match_over_fresh_result_scrutinee_does_not_leak_end_to_end() {
    let src = "fn first_ok(a: str, b: str) -> Result<str, str>:\n    \
               if len(a) > 0:\n        return Result<str, str>::Ok(a)\n    Result<str, str>::Err(b)\n\n\
               fn unwrap_str(a: str) -> str:\n    \
               match first_ok(a, \"fallback\"):\n        Result::Ok(v) -> v\n        Result::Err(e) -> e\n\n\
               fn main():\n    let mut i: i32 = 0\n    \
               while i < 400000:\n        let r = unwrap_str(concat(\"item\", \"x\"))\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("match_fresh_result_scrutinee_leak", src, 20 * 1024 * 1024);
}

/// The same fix, exercised through `expr?` specifically -- `Checker::
/// infer_try` desugars `?` into exactly the `TypedExpr::Match` shape the
/// test above targets directly (see its own doc comment), so `?`-
/// propagation through a nested call leaked identically before this round's
/// fix. Confirmed via real unbounded working-set growth (~27MB -> 210MB+
/// within 3 seconds) before this fix.
#[test]
fn runtime_try_operator_propagation_does_not_leak_end_to_end() {
    let src = "fn first_ok(a: str, b: str) -> Result<str, str>:\n    \
               if len(a) > 0:\n        return Result<str, str>::Ok(a)\n    Result<str, str>::Err(b)\n\n\
               fn double_wrap(a: str) -> Result<str, str>:\n    \
               let h = first_ok(a, \"fallback\")?\n    Result<str, str>::Ok(concat(h, \"!\"))\n\n\
               fn main():\n    let mut i: i32 = 0\n    \
               while i < 400000:\n        let r = double_wrap(concat(\"item\", \"x\"))\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("try_operator_propagation_leak", src, 20 * 1024 * 1024);
}

/// Control for the `match`-scrutinee-leak fix above: a `match` over a
/// *real* place scrutinee (a struct field, not a fresh call result) must
/// still work correctly and must NOT be double-tracked/double-released --
/// `h.opt`'s own storage is already owned by `h`'s own scope-exit release,
/// so `Codegen::emit_place`'s dedicated `Field` arm (not its generic
/// fallback) resolves it, and no extra tracking happens. This test's
/// oracle is correct *output* across many iterations (not just flat
/// memory), so a double-free corrupting the string would show up as a
/// wrong/garbled result or a crash instead of just a leak.
#[test]
fn runtime_match_over_struct_field_option_scrutinee_still_correct_end_to_end() {
    let src = "struct Holder:\n    opt: Option<str>\n\n\
               fn main():\n    let mut i: i32 = 0\n    let mut last: i32 = -1\n    \
               while i < 200000:\n        let h = Holder(opt = Option::Some(concat(\"item\", \"x\")))\n        \
               let v = match h.opt:\n            Option::Some(s) -> len(s)\n            Option::None -> -1\n        \
               last = v\n        i += 1\n    println(f\"{last}\")\n";
    let output = compile_and_run("match_struct_field_option_scrutinee_control", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "5", "concat(\"item\", \"x\") == \"itemx\" is 5 bytes long: {:?}", output.stdout);
}

/// A struct declared *anywhere* in the source with an `Option<T>`/
/// `Result<T,E>`-typed field (a payload enum) previously baked a
/// permanently wrong LLVM struct type declaration for itself:
/// `Codegen::emit` registered and emitted every struct's/enum's LLVM type
/// in one interleaved pass, in `module.items` order -- but every
/// monomorphized generic enum instantiation (`Option<str>` -> the concrete
/// `Option__str`, appended to the item list by `Checker::check` *after*
/// every item that appears in the source, regardless of where in the
/// source it was first used) is always ordered after a struct that
/// references it. So `Holder`'s own field-type computation
/// (`llvm_ty(Ty::Enum("Option__str"))`, which depends on `enum_is_payload`
/// reading `enum_variant_fields`) always ran before `Option__str`'s own
/// registration, silently defaulting `enum_is_payload` to `false` and
/// mistagging the field as a bare `i32` in `Holder`'s permanent `%Holder =
/// type { .. }` text instead of the real multi-word `%Option__str` tagged
/// union. Every later store of a full `Option<str>` value into that field
/// then wrote past the single `i32` slot LLVM/`clang` had actually sized
/// for it, corrupting adjacent stack memory. Confirmed via a real `star
/// build`+run segfaulting (`ExitStatus` `0xC0000005`, an access violation)
/// on exactly this minimal shape -- one loop iteration, no `Table`/`Ring`/
/// nested-generics involved at all -- before this fix. Fixed by splitting
/// registration (`Codegen::register_struct`/`register_enum`, populating
/// `struct_field_types`/`enum_variant_fields` with no LLVM text emitted)
/// out of text emission (`emit_struct_decl`/`emit_enum_decl`) into two
/// separate passes over every item, so every enum a struct field might
/// reference (and vice versa) is fully registered before any type's text
/// is emitted -- LLVM's textual IR allows named struct types to reference
/// each other regardless of which is declared first, so only the
/// *registration data* needed reordering, not the emitted text itself.
#[test]
fn runtime_struct_field_typed_as_generic_payload_enum_end_to_end() {
    let src = "struct Holder:\n    opt: Option<str>\n\n\
               fn main():\n    let h = Holder(opt = Option::Some(concat(\"hello\", \" world\")))\n    \
               match h.opt:\n        Option::Some(s) -> println(s)\n        Option::None -> println(\"none\")\n";
    let output = compile_and_run("struct_field_generic_payload_enum", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "hello world");
}

/// Same bug, `Result<T,E>` instead of `Option<T>` (a two-type-argument
/// generic enum, wider payload than `Option`'s single-field `Some`) as a
/// struct field, plus a second, unrelated struct declared *after* it in
/// source order -- guards against the fix only working for the first
/// struct/enum pair in the module or only for the single-type-argument
/// case.
#[test]
fn runtime_struct_field_typed_as_generic_result_end_to_end() {
    let src = "struct Holder:\n    res: Result<i32, str>\n\nstruct Other:\n    tag: i32\n\n\
               fn main():\n    let h = Holder(res = Result<i32, str>::Ok(42))\n    let o = Other(tag = 7)\n    \
               match h.res:\n        Result::Ok(v) -> println(f\"ok:{v}\")\n        Result::Err(e) -> println(f\"err:{e}\")\n    \
               println(f\"other:{o.tag}\")\n";
    let output = compile_and_run("struct_field_generic_result", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(stdout.lines().collect::<Vec<_>>(), vec!["ok:42", "other:7"], "{}", stdout);
}

// =====================================================================
// ===== Bug-hunting round 3 (memory/RC x concurrency/collections =======
// ===== intersection audit): unlike round 2's single-feature audits ====
// ===== (which found real `Ty::Enum`-RC-walk and generic-fallback-spill
// ===== leaks), this round specifically targeted combinations a single- ==
// ===== feature repro wouldn't hit -- `List`/`Map`/`Table`/`Ring` of ====
// ===== `Option`/`Result`-payload elements under sustained push/pop/CoW-
// ===== clone, `par`/`swarm` bodies constructing/dropping RC-bearing ===
// ===== locals per iteration across many dispatch/join cycles, arena ===
// ===== `spawn`/`despawn` cycling with an `Option`/`List`-bearing struct
// ===== field, `sequence` coroutines abandoned mid-way with an RC-local
// ===== still live across a `yield`, and `match` on a fresh payload-enum
// ===== scrutinee inside a `par`/`swarm` body's own separate worker
// ===== function. Every candidate below was reproduced via a real
// ===== `star build -O2`+run first, sampling actual process Working Set
// ===== over millions of iterations (see this round's own report for the
// ===== exact numbers) -- every one came back flat, matching an
// ===== RC-free control of the same shape. No new bugs were found: round
// ===== 2's `Ty::Enum` RC-walk (`src/codegen/rc.rs`) and generic-fallback
// ===== spill-tracking fix (`src/codegen/mod.rs`'s `emit_place`) already
// ===== compose correctly across every one of these combinations, and
// ===== `par`/`swarm`'s own per-callsite worker function
// ===== (`Codegen::emit_par_stmt`, `src/codegen/arena.rs`) already swaps
// ===== in a fresh `owned_stack`/`push_scope`/`pop_scope` per iteration
// ===== exactly like an ordinary function body. The tests below convert
// ===== this round's clean empirical findings into permanent regression
// ===== coverage (using the same `assert_no_leak` Working-Set-delta
// ===== helper as round 2's leak tests above) so a future change that
// ===== reintroduces a leak in one of these specific combinations is
// ===== caught immediately instead of needing another manual audit. =====

/// `List<Option<str>>` (collections-of-generics x the round-2 `Ty::Enum`
/// RC-walk fix): sustained `push`/`pop` churn, keeping the list's length
/// bounded (so growth can't be explained by an ever-growing buffer) while
/// every pushed element is a fresh `Option::Some(str)` payload. Manually
/// confirmed flat (~2.7MB, zero measurable growth) over 40,000,000
/// iterations at `-O2` before this test was written; scaled down to a size
/// that still reliably shows a reintroduced leak (each iteration owns one
/// heap-allocated `str` payload) within this file's usual ~20MB cap.
#[test]
fn runtime_list_of_option_str_sustained_push_pop_does_not_leak_end_to_end() {
    let src = "fn main():\n    let mut lst: List<Option<str>> = List<Option<str>>()\n    let mut i: i32 = 0\n    \
               while i < 400000:\n        lst.push(Option::Some(concat(\"item\", \"x\")))\n        \
               if lst.len() > 50:\n            lst.pop()\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("list_option_str_sustained_push_pop_leak", src, 20 * 1024 * 1024);
}

/// `Table<T>` (struct-of-arrays) where `T` has an `Option<str>` column --
/// exercises the per-column release thunk (`crate::codegen::table::
/// table_release_thunk_operand`) against a payload-enum column
/// specifically, under sustained `push`/`pop` churn identical in shape to
/// the `List<Option<str>>` test above. Manually confirmed flat over
/// 25,000,000 iterations at `-O2` (both the plain append/pop loop and a
/// separate copy-on-write-clone stress variant sharing the table between
/// two owners every iteration) before this test was written.
#[test]
fn runtime_table_option_field_sustained_push_pop_does_not_leak_end_to_end() {
    let src = "struct Item:\n    tag: Option<str>\n    hp: i32\n\n\
               fn main():\n    let mut t: Table<Item> = Table<Item>()\n    let mut i: i32 = 0\n    \
               while i < 300000:\n        t.push(Item(tag = Option::Some(concat(\"tag\", \"x\")), hp = i))\n        \
               if t.len() > 50:\n            t.pop()\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("table_option_field_sustained_push_pop_leak", src, 20 * 1024 * 1024);
}

/// `par` dispatched across many ticks, each iteration's per-arena-entry
/// worker body constructing and dropping its own local `List<str>` and
/// `Option<str>` (never captured, never escaping) -- the specific
/// concurrency x memory-model combination this round targeted: does the
/// persistent thread pool (`src/codegen/par_pool.rs`) correctly release a
/// worker-local RC-bearing temporary on *every* dispatch, not just the
/// first/last? `Codegen::emit_par_stmt` (`src/codegen/arena.rs`) swaps in a
/// fresh `owned_stack` per worker function and calls `push_scope`/
/// `pop_scope` once per arena element visited, same as an ordinary loop
/// body. Manually confirmed flat (~3.1MB, zero measurable growth) over
/// 600,000 dispatch/join cycles (16 arena entries each, ~9,600,000 total
/// worker-body executions) at `-O2` before this test was written; scaled
/// down here since a `par` dispatch's own OS-semaphore handoff overhead
/// dominates at `-O0`.
#[test]
fn runtime_par_body_per_iteration_rc_locals_does_not_leak_end_to_end() {
    let src = "struct Enemy:\n    mut hp: i32\n\narena Enemies: Enemy\n\n\
               fn main():\n    let mut i: i32 = 0\n    while i < 16:\n        spawn Enemies(100)\n        i += 1\n    \
               let mut tick: i32 = 0\n    while tick < 20000:\n        \
               par e in Enemies:\n            let mut lst: List<str> = List<str>()\n            \
               lst.push(concat(\"x\", \"y\"))\n            \
               let opt: Option<str> = Option::Some(concat(\"a\", \"b\"))\n            \
               e.hp -= 1\n        tick += 1\n    \
               println(\"done\")\n";
    assert_no_leak("par_body_per_iteration_rc_locals_leak", src, 20 * 1024 * 1024);
}

/// Arena `spawn`/`despawn` cycling (never growing past one live slot) where
/// the spawned struct has an `Option<str>` field -- the specific gap round
/// 2's arena audit noted but didn't explicitly cover ("no bugs found" was
/// verified against a plain-data element type, not an `Option`/`Result`-
/// bearing one). `Codegen::emit_despawn_stmt` releases the slot's RC-bearing
/// content on despawn, and `emit_spawn_stmt` never re-releases a reused
/// slot's *previous* occupant (already released by the despawn that freed
/// it) -- both already correct for a plain `str` field per round 2's own
/// `runtime_stale_genref_field_write_does_not_leak_end_to_end`-style tests,
/// but not yet exercised against an `Option<T>` field specifically. Manually
/// confirmed flat over 25,000,000 despawn/spawn cycles at `-O2` before this
/// test was written.
#[test]
fn runtime_arena_spawn_despawn_cycle_with_option_field_does_not_leak_end_to_end() {
    let src = "struct Item:\n    tag: Option<str>\n    hp: i32\n\narena Items: Item\n\n\
               fn main():\n    spawn Items(Option::Some(concat(\"seed\", \"x\")), 0)\n    let mut i: i32 = 0\n    \
               while i < 300000:\n        despawn Items[0]\n        \
               spawn Items(Option::Some(concat(\"cycle\", \"x\")), i)\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("arena_spawn_despawn_option_field_cycle_leak", src, 20 * 1024 * 1024);
}

/// A `sequence` coroutine with a `str` local reassigned across `yield`
/// points, `resume()`'d exactly once (never run to completion) and then
/// dropped -- since `src/sequence.rs` desugars a `sequence` into a plain
/// `struct` + `resume(mut self) -> bool` method (see that module's own doc
/// comment), the hoisted local becomes an ordinary struct field, and an
/// abandoned-mid-sequence instance is released the same way any other
/// struct instance with RC-bearing fields is at scope exit -- no
/// coroutine-specific release logic exists or is needed. This test locks in
/// that behavior for the specific "abandoned before completion" case (the
/// case a naive coroutine implementation would most plausibly get wrong,
/// e.g. by only releasing hoisted locals along the "ran to completion"
/// path). Manually confirmed flat over 25,000,000 create-resume-once-drop
/// cycles at `-O2` before this test was written.
#[test]
fn runtime_sequence_abandoned_mid_way_releases_rc_local_end_to_end() {
    let src = "sequence Chatter(seed: str):\n    let mut msg: str = concat(seed, \"-1\")\n    yield\n    \
               msg = concat(seed, \"-2\")\n    yield\n    msg = concat(seed, \"-3\")\n    print(msg)\n\n\
               fn main():\n    let mut i: i32 = 0\n    while i < 300000:\n        \
               let mut c = Chatter(concat(\"s\", \"eed\"))\n        c.resume()\n        i += 1\n    \
               println(\"done\")\n";
    assert_no_leak("sequence_abandoned_mid_way_leak", src, 20 * 1024 * 1024);
}

/// `match` on a *fresh* (non-place) payload-enum scrutinee -- round 2's bug
/// #4, addressed generally via `Codegen::emit_place`'s generic fallback --
/// specifically inside a `par`/`swarm` body's own separate worker function
/// (`Codegen::emit_par_stmt` builds an entirely distinct top-level LLVM
/// function per callsite, a different function boundary than the plain
/// top-level `fn` round 2's own regression test exercises), and nested two
/// levels deep (`par` inside `par`, which falls back to the manually-
/// reentrant serial path in `src/codegen/par_pool.rs` rather than the
/// pooled dispatch). Manually confirmed flat over 60,000 outer ticks (6x6
/// entries each, 2,160,000 total nested-match executions) at `-O2` before
/// this test was written; scaled down here for `-O0` dispatch overhead.
#[test]
fn runtime_match_over_fresh_enum_inside_nested_par_does_not_leak_end_to_end() {
    let src = "struct Enemy:\n    mut hp: i32\nstruct Bullet:\n    mut dmg: i32\n\
               arena Enemies: Enemy\narena Bullets: Bullet\n\n\
               fn make_opt(v: i32) -> Option<str>:\n    if v > 0:\n        return Option::Some(concat(\"p\", \"x\"))\n    \
               Option<str>::None\n\n\
               fn main():\n    let mut i: i32 = 0\n    while i < 4:\n        spawn Enemies(1)\n        i += 1\n    \
               let mut j: i32 = 0\n    while j < 4:\n        spawn Bullets(0)\n        j += 1\n    \
               let mut tick: i32 = 0\n    while tick < 8000:\n        \
               par e in Enemies:\n            par b in Bullets:\n                \
               match make_opt(b.dmg):\n                    Option::Some(s) ->\n                        \
               b.dmg = b.dmg + len(s)\n                    Option::None ->\n                        \
               b.dmg = b.dmg - 1\n        tick += 1\n    \
               println(\"done\")\n";
    assert_no_leak("match_fresh_enum_inside_nested_par_leak", src, 20 * 1024 * 1024);
}

// ===== `BitField<N>` / `Flags<E>` (docs/design.md §8, "Bit-level types") ===

/// Construction from an int-shaped value, widened/narrowed to `i{N}` --
/// mirrors `Ty::Tick`'s own construction rule, see `examples/bitfield.star`.
#[test]
fn runtime_bitfield_construction_and_print_end_to_end() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(200 as u8)\n    println(f\"{a}\")\n";
    let output = compile_and_run("bitfield_construct", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "200");
}

/// A literal wider than `i32`'s range (so `Checker::infer_expr`'s literal-
/// magnitude fast path is what makes this legal at all -- an ordinary bare
/// literal token defaults to `i32`) still constructs a `BitField<64>`
/// correctly, tagged with the matching-width type rather than truncated back
/// down to `i32` by the fast path itself.
#[test]
fn runtime_bitfield_construction_from_wide_literal_end_to_end() {
    let src = "fn main():\n    let a: BitField<64> = BitField<64>(5000000000)\n    println(f\"{a}\")\n";
    let output = compile_and_run("bitfield_wide_literal", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "5000000000");
}

/// Construction from a value *wider* than `N` truncates (matching `as`'s own
/// infallible truncating semantics -- there's no fallible-construction path
/// in this compiler), same as a non-literal source would have to.
#[test]
fn runtime_bitfield_construction_truncates_wider_source_end_to_end() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(300)\n    println(f\"{a}\")\n";
    let output = compile_and_run("bitfield_truncate", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "44");
}

/// `bit_set`/`bit_get`/`bit_clear`/`bit_toggle` -- the index-based free-
/// function surface (`&`/`|`/`^`/`~` don't exist as operators in this
/// language yet, see `Ty::BitField`'s doc comment).
#[test]
fn runtime_bitfield_set_get_clear_toggle_end_to_end() {
    let src = "fn main():\n    let mut a: BitField<8> = BitField<8>(0)\n    a = bit_set(a, 0)\n    a = bit_set(a, 3)\n    \
               println(f\"{a}\")\n    println(f\"{bit_get(a, 0)}\")\n    println(f\"{bit_get(a, 1)}\")\n    \
               a = bit_clear(a, 3)\n    println(f\"{a}\")\n    a = bit_toggle(a, 1)\n    println(f\"{a}\")\n";
    let output = compile_and_run("bitfield_set_get_clear_toggle", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["9", "true", "false", "1", "3"], "{}", stdout);
}

/// An out-of-range bit index (`>= N`) shifts by a truncated/wrapped amount
/// rather than trapping -- matching this compiler's existing "safe, not
/// panicking" convention for other builtin edge cases (e.g. an out-of-bounds
/// `List<T>` index). `9` truncated to 3 bits (mod 8) is `1`, so `bit_get(a,
/// 9)` reads the same bit as `bit_get(a, 1)`.
#[test]
fn runtime_bitfield_out_of_range_index_wraps_rather_than_traps_end_to_end() {
    let src = "fn main():\n    println(\"before\")\n    let a: BitField<8> = BitField<8>(2 as u8)\n    \
               println(f\"{bit_get(a, 1)}\")\n    println(f\"{bit_get(a, 9)}\")\n    println(\"after\")\n";
    let output = compile_and_run("bitfield_oob_index", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["before", "true", "true", "after"], "{}", stdout);
}

/// `bit_and`/`bit_or`/`bit_xor`/`bit_not` combine whole registers.
#[test]
fn runtime_bitfield_and_or_xor_not_end_to_end() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(12 as u8)\n    let b: BitField<8> = BitField<8>(10 as u8)\n    \
               println(f\"{bit_and(a, b)}\")\n    println(f\"{bit_or(a, b)}\")\n    println(f\"{bit_xor(a, b)}\")\n    println(f\"{bit_not(a)}\")\n";
    let output = compile_and_run("bitfield_and_or_xor_not", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["8", "14", "6", "243"], "{}", stdout);
}

/// `==`/`!=` -- a single bit-pattern comparison, see `Ty::BitField`'s doc
/// comment.
#[test]
fn runtime_bitfield_equality_end_to_end() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(5 as u8)\n    let b: BitField<8> = BitField<8>(5 as u8)\n    \
               let c: BitField<8> = BitField<8>(6 as u8)\n    println(f\"{a == b}\")\n    println(f\"{a != c}\")\n    println(f\"{a == c}\")\n";
    let output = compile_and_run("bitfield_equality", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "true", "false"], "{}", stdout);
}

/// `BitField<N> <-> u{N}` is a free bit-preserving relabel via `as`.
#[test]
fn runtime_bitfield_cast_round_trip_end_to_end() {
    let src = "fn main():\n    let a: BitField<16> = BitField<16>(1000)\n    let raw: u16 = a as u16\n    println(f\"{raw}\")\n    \
               let back: BitField<16> = raw as BitField<16>\n    println(f\"{a == back}\")\n";
    let output = compile_and_run("bitfield_cast_roundtrip", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["1000", "true"], "{}", stdout);
}

/// `BitField<N>` also allows casting to/from the *signed* type at the
/// matching width (`i16`, not just `u16`) -- it has no declared signedness
/// of its own (a bit count, not a stored `Ty`), unlike `Wrapping<T>`'s
/// exact-`Ty`-match cast rule.
#[test]
fn runtime_bitfield_cast_to_signed_type_at_same_width_end_to_end() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(200 as u8)\n    let signed: i8 = a as i8\n    println(f\"{signed}\")\n";
    let output = compile_and_run("bitfield_cast_signed", src);
    assert!(output.status.success(), "{:?}", output.status);
    // 200 as an 8-bit two's-complement pattern reinterpreted signed is -56.
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "-56");
}

/// Every supported width (`8`/`16`/`32`/`64`) lowers correctly, not just the
/// smallest -- `bit_set` on the top bit of a wide register.
#[test]
fn runtime_bitfield_widths_32_and_64_end_to_end() {
    let src = "fn main():\n    let mut a: BitField<32> = BitField<32>(0)\n    a = bit_set(a, 31)\n    println(f\"{a}\")\n    \
               let mut b: BitField<64> = BitField<64>(0)\n    b = bit_set(b, 63)\n    println(f\"{b}\")\n";
    let output = compile_and_run("bitfield_wide_widths", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["2147483648", "9223372036854775808"], "{}", stdout);
}

/// The `bit_*` free functions aren't restricted to `BitField<N>` itself --
/// they also work on a plain integer type and on `Wrapping<T>` (`Ty::
/// bit_shape`'s full set), the retro-register-emulation use case `docs/
/// design.md`'s "Bit-level types" section motivates this section with.
#[test]
fn runtime_bit_ops_on_plain_int_and_wrapping_end_to_end() {
    let src = "fn main():\n    let reg: i32 = 0\n    let reg2 = bit_set(reg, 4)\n    println(f\"{reg2}\")\n    \
               let w: Wrapping<u8> = Wrapping<u8>(0 as u8)\n    let w2 = bit_set(w, 7)\n    println(f\"{w2}\")\n";
    let output = compile_and_run("bit_ops_plain_int_wrapping", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["16", "128"], "{}", stdout);
}

/// `BitField<N>` is structurally hashable (a bare `i{N}` comparison, like
/// `Symbol`) -- legal as a `Set<T>` element. Mirrors `runtime_symbol_as_
/// set_key_dedups_end_to_end`'s regression-test shape: `crate::codegen::eq`'s
/// generated per-key-type equality function relies on every legal `Map`/
/// `Set` key type having its own explicit arm, silently falling back to
/// "always equal" otherwise (the exact bug class `Ty::Symbol` once shipped
/// with, see `docs/design.md`) -- if `Ty::BitField` were missing its own
/// `emit_eq_body` arm, every distinct value would collapse into one slot and
/// this would report `1`, not `3`.
#[test]
fn runtime_bitfield_as_set_key_dedups_correctly_end_to_end() {
    let src = "fn main():\n    let mut s: Set<BitField<8>> = Set<BitField<8>>()\n    \
               s.insert(BitField<8>(1 as u8))\n    s.insert(BitField<8>(2 as u8))\n    s.insert(BitField<8>(1 as u8))\n    \
               s.insert(BitField<8>(3 as u8))\n    println(f\"{s.len()}\")\n";
    let output = compile_and_run("bitfield_set_key_dedup", src);
    assert!(output.status.success(), "{:?}", output.status);
    assert_eq!(String::from_utf8_lossy(&output.stdout).trim(), "3");
}

#[test]
fn rejects_bitfield_with_an_unsupported_bit_width() {
    let src = "fn main():\n    let a: BitField<7> = BitField<7>(1)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("bit width must be one of 8, 16, 32, 64")), "{:?}", diags);
}

#[test]
fn rejects_bitfield_construction_with_non_integer_value() {
    let src = "fn main():\n    let a = BitField<8>(\"nope\")\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("expects an integer value")), "{:?}", diags);
}

#[test]
fn rejects_bit_get_with_non_integer_index() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(1 as u8)\n    let b = bit_get(a, \"x\")\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("bit index) expected `int`")), "{:?}", diags);
}

#[test]
fn rejects_bit_and_between_mismatched_bitfield_widths() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(1 as u8)\n    let b: BitField<16> = BitField<16>(1)\n    let c = bit_and(a, b)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("must be the same type")), "{:?}", diags);
}

#[test]
fn rejects_binop_between_mismatched_bitfield_widths() {
    let src = "fn main():\n    let a: BitField<8> = BitField<8>(1 as u8)\n    let b: BitField<16> = BitField<16>(1)\n    let c = a == b\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("is not supported between")), "{:?}", diags);
}

#[test]
fn rejects_bit_not_on_a_flags_value() {
    let src = "enum Dir:\n    Up\n    Down\n\nfn main():\n    let f: Flags<Dir> = Flags<Dir>()\n    let g = bit_not(f)\n";
    let module = Driver::parse(src).expect("should parse");
    let diags = Driver::check(&module).expect_err("should fail to type-check");
    assert!(diags.iter().any(|d| d.message.contains("expects an integer/`Wrapping<T>`/`BitField<N>` value")), "{:?}", diags);
}

/// `Flags<E>()` starts empty; `flags_with`/`flags_without`/`flags_has`/
/// `flags_is_empty` build it up and query it -- see `examples/flags.star`.
#[test]
fn runtime_flags_construction_with_without_has_is_empty_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n    Left\n    Right\n\n\
               fn main():\n    let mut m: Flags<Direction> = Flags<Direction>()\n    println(f\"{flags_is_empty(m)}\")\n    \
               m = flags_with(m, Direction::Up)\n    println(f\"{flags_has(m, Direction::Up)}\")\n    \
               println(f\"{flags_has(m, Direction::Down)}\")\n    println(f\"{flags_is_empty(m)}\")\n    \
               m = flags_without(m, Direction::Up)\n    println(f\"{flags_has(m, Direction::Up)}\")\n    \
               println(f\"{flags_is_empty(m)}\")\n";
    let output = compile_and_run("flags_construct_with_without", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "true", "false", "false", "false", "true"], "{}", stdout);
}

/// `Flags<E>(a, b, ...)` -- variadic direct construction from multiple
/// variants at once, OR'd together.
#[test]
fn runtime_flags_variadic_construction_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n    Left\n    Right\n\n\
               fn main():\n    let diagonal: Flags<Direction> = Flags<Direction>(Direction::Up, Direction::Right)\n    \
               println(f\"{flags_has(diagonal, Direction::Up)}\")\n    println(f\"{flags_has(diagonal, Direction::Down)}\")\n    \
               println(f\"{flags_has(diagonal, Direction::Left)}\")\n    println(f\"{flags_has(diagonal, Direction::Right)}\")\n";
    let output = compile_and_run("flags_variadic_construct", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "false", "false", "true"], "{}", stdout);
}

/// A *runtime* (non-literal) enum-typed expression works as a `Flags<E>`
/// construction argument too, not just a literal `EnumName::Variant` --
/// `Codegen::emit_flags_variant_bit` computes `1i64 << discriminant` from
/// the already-evaluated value, with no compile-time variant-name lookup.
#[test]
fn runtime_flags_construction_from_runtime_enum_value_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n    Left\n    Right\n\n\
               fn main():\n    let dir: Direction = Direction::Left\n    let f: Flags<Direction> = Flags<Direction>(dir)\n    \
               println(f\"{flags_has(f, Direction::Left)}\")\n    println(f\"{flags_has(f, Direction::Up)}\")\n";
    let output = compile_and_run("flags_from_runtime_enum", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "false"], "{}", stdout);
}

/// `bit_or`/`bit_and`/`bit_xor` on `Flags<E>` implement union/intersect/
/// symmetric-difference -- safe to share with `Ty::BitField`'s free
/// functions since both operands only ever have bits set for real declared
/// variants (see `Ty::Flags`'s doc comment).
#[test]
fn runtime_flags_union_intersect_symmetric_difference_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n    Left\n    Right\n\n\
               fn main():\n    let all_four: Flags<Direction> = Flags<Direction>(Direction::Up, Direction::Down, Direction::Left, Direction::Right)\n    \
               let vertical: Flags<Direction> = Flags<Direction>(Direction::Up, Direction::Down)\n    \
               let horizontal: Flags<Direction> = Flags<Direction>(Direction::Left, Direction::Right)\n    \
               let empty: Flags<Direction> = Flags<Direction>()\n    \
               println(f\"{bit_or(vertical, horizontal) == all_four}\")\n    \
               println(f\"{bit_and(vertical, horizontal) == empty}\")\n    \
               println(f\"{bit_xor(all_four, vertical) == horizontal}\")\n";
    let output = compile_and_run("flags_union_intersect_symdiff", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "true", "true"], "{}", stdout);
}

/// `==`/`!=` and `Flags<E> as i64` (a free bit-preserving relabel, for
/// debugging -- printing the raw mask).
#[test]
fn runtime_flags_equality_and_cast_to_i64_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n    Left\n    Right\n\n\
               fn main():\n    let a: Flags<Direction> = Flags<Direction>(Direction::Up, Direction::Down)\n    \
               let b: Flags<Direction> = Flags<Direction>(Direction::Up, Direction::Down)\n    \
               let c: Flags<Direction> = Flags<Direction>(Direction::Left)\n    \
               println(f\"{a == b}\")\n    println(f\"{a != c}\")\n    \
               let raw: i64 = a as i64\n    println(f\"{raw}\")\n";
    let output = compile_and_run("flags_equality_cast", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "true", "3"], "{}", stdout);
}

/// `Flags<E>` is structurally hashable -- legal as a `Map<K,V>` key. Same
/// "needs its own explicit `emit_eq_body` arm" regression-test reasoning as
/// `runtime_bitfield_as_set_key_dedups_correctly_end_to_end` above.
#[test]
fn runtime_flags_as_map_key_end_to_end() {
    let src = "enum Direction:\n    Up\n    Down\n\n\
               fn main():\n    let mut m: Map<Flags<Direction>, i32> = Map<Flags<Direction>, i32>()\n    \
               m.insert(Flags<Direction>(Direction::Up), 1)\n    m.insert(Flags<Direction>(Direction::Down), 2)\n    \
               m.insert(Flags<Direction>(Direction::Up), 3)\n    println(f\"{m.len()}\")\n    \
               let v = m.get(Flags<Direction>(Direction::Up))\n    \
               match v:\n        Option::Some(x) -> println(f\"{x}\")\n        Option::None -> println(\"missing\")\n";
    let output = compile_and_run("flags_as_map_key", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["2", "3"], "{}", stdout);
}

