/// `reflect_has_field` is `true` for a decorated field, `false` for an
/// undecorated field of the same struct, and `false` for a name that
/// doesn't exist on the struct at all.
#[test]
fn runtime_reflect_has_field_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export mut score: i32 = 0\n",
        "    name: str = \"Hero\"\n",
        "\n",
        "fn main():\n",
        "    let s = Stats(score = 0, name = \"x\")\n",
        "    let a = reflect_has_field(s, \"score\")\n",
        "    let b = reflect_has_field(s, \"name\")\n",
        "    let c = reflect_has_field(s, \"nonexistent\")\n",
        "    println(f\"{a}\")\n",
        "    println(f\"{b}\")\n",
        "    println(f\"{c}\")\n",
    );
    let output = compile_and_run("reflect_has_field", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["true", "false", "false"], "{}", stdout);
}

/// A decorated-but-not-`mut` field is excluded from `reflect_set_i32`'s
/// generated accessor entirely (`codegen_reflect_set_i32_accessor_excludes_non_mut_field`'s
/// runtime counterpart): writing to its name is a safe no-op, exactly as if
/// the name didn't match anything at all, while a genuinely `mut` decorated
/// field of the same struct still writes correctly.
#[test]
fn runtime_reflect_set_skips_non_mut_decorated_field_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export health: i32 = 100\n",
        "    @tweakable mut speed: i32 = 5\n",
        "\n",
        "fn main():\n",
        "    let mut s = Stats(health = 100, speed = 5)\n",
        "    reflect_set_i32(s, \"health\", 999)\n",
        "    reflect_set_i32(s, \"speed\", 42)\n",
        "    println(f\"{s.health}\")\n",
        "    println(f\"{s.speed}\")\n",
    );
    let output = compile_and_run("reflect_skips_non_mut", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["100", "42"], "{}", stdout);
}

/// `reflect_set_i32(self, ..)` works from inside an `impl` method exactly
/// like it does on an ordinary local -- `emit_place`'s `SelfExpr` arm
/// resolves `self` to a real pointer the same way plain `self.field`
/// codegen already does.
#[test]
fn runtime_reflect_via_self_in_method_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export mut score: i32 = 0\n",
        "\n",
        "impl Stats:\n",
        "    fn apply_tweak(mut self, name: str, value: i32):\n",
        "        reflect_set_i32(self, name, value)\n",
        "\n",
        "fn main():\n",
        "    let mut s = Stats(score = 5)\n",
        "    s.apply_tweak(\"score\", 77)\n",
        "    println(f\"{s.score}\")\n",
    );
    let output = compile_and_run("reflect_via_self", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["77"], "{}", stdout);
}

/// `reflect_set_i32` through a `Field` chain (`container.stats`, where
/// `stats` is itself a `mut` field of `Container`) resolves through
/// `emit_place`'s recursive `Field` arm to the real nested storage, and
/// `check_mut_receiver`'s field-level `mut` gate (`Checker::field_is_mut`)
/// correctly allows it since `stats` is declared `mut`.
#[test]
fn runtime_reflect_set_through_mut_field_chain_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export mut score: i32 = 0\n",
        "struct Container:\n",
        "    mut stats: Stats = Stats(score = 0)\n",
        "\n",
        "fn main():\n",
        "    let mut c = Container(stats = Stats(score = 1))\n",
        "    reflect_set_i32(c.stats, \"score\", 99)\n",
        "    println(f\"{c.stats.score}\")\n",
    );
    let output = compile_and_run("reflect_field_chain", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["99"], "{}", stdout);
}

/// Two unrelated structs decorating a field with the *same* name (`score`)
/// must not cross-contaminate -- each struct gets its own generated
/// accessor function (keyed by struct name), even though the underlying
/// `"score"` field-name string constant those two accessors' `strcmp`
/// chains compare against is deduplicated and shared between them
/// (`Codegen::reflect_name_ptr`).
#[test]
fn runtime_reflect_two_structs_with_same_field_name_do_not_collide_end_to_end() {
    let src = concat!(
        "struct A:\n",
        "    @export mut score: i32 = 0\n",
        "struct B:\n",
        "    @export mut score: i32 = 0\n",
        "\n",
        "fn main():\n",
        "    let mut a = A(score = 1)\n",
        "    let mut b = B(score = 2)\n",
        "    reflect_set_i32(a, \"score\", 111)\n",
        "    reflect_set_i32(b, \"score\", 222)\n",
        "    let av = reflect_get_i32(a, \"score\")\n",
        "    let bv = reflect_get_i32(b, \"score\")\n",
        "    println(f\"{av}\")\n",
        "    println(f\"{bv}\")\n",
    );
    let output = compile_and_run("reflect_two_structs_same_name", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["111", "222"], "{}", stdout);
}

/// A struct with several decorated `i32` fields resolves each runtime name
/// to the *correct* field, not just "the first one" or "the last one" --
/// exercising the generated `strcmp` chain past a single comparison.
#[test]
fn runtime_reflect_multiple_decorated_fields_picks_correct_one_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export mut a: i32 = 1\n",
        "    @export mut b: i32 = 2\n",
        "    @export mut c: i32 = 3\n",
        "    @export mut d: i32 = 4\n",
        "\n",
        "fn main():\n",
        "    let mut s = Stats(a = 1, b = 2, c = 3, d = 4)\n",
        "    let va = reflect_get_i32(s, \"a\")\n",
        "    let vb = reflect_get_i32(s, \"b\")\n",
        "    let vc = reflect_get_i32(s, \"c\")\n",
        "    let vd = reflect_get_i32(s, \"d\")\n",
        "    println(f\"{va}\")\n",
        "    println(f\"{vb}\")\n",
        "    println(f\"{vc}\")\n",
        "    println(f\"{vd}\")\n",
        "    reflect_set_i32(s, \"c\", 300)\n",
        "    println(f\"{s.a}\")\n",
        "    println(f\"{s.b}\")\n",
        "    println(f\"{s.c}\")\n",
        "    println(f\"{s.d}\")\n",
    );
    let output = compile_and_run("reflect_multi_field", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["1", "2", "3", "4", "1", "2", "300", "4"], "{}", stdout);
}

/// `@export` and `@tweakable` are interchangeable as far as
/// `reflect_get_*`/`reflect_set_*` are concerned -- either decorator alone
/// (or both stacked) makes a field reflectable, matching
/// `emit_reflect_metadata`'s own "any decorator at all" gate.
#[test]
fn runtime_reflect_export_and_tweakable_both_reflectable_end_to_end() {
    let src = concat!(
        "struct Stats:\n",
        "    @export mut exported_only: i32 = 1\n",
        "    @tweakable mut tweakable_only: i32 = 2\n",
        "    @export @tweakable mut both: i32 = 3\n",
        "\n",
        "fn main():\n",
        "    let mut s = Stats(exported_only = 1, tweakable_only = 2, both = 3)\n",
        "    reflect_set_i32(s, \"exported_only\", 10)\n",
        "    reflect_set_i32(s, \"tweakable_only\", 20)\n",
        "    reflect_set_i32(s, \"both\", 30)\n",
        "    println(f\"{s.exported_only}\")\n",
        "    println(f\"{s.tweakable_only}\")\n",
        "    println(f\"{s.both}\")\n",
    );
    let output = compile_and_run("reflect_export_tweakable", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines, vec!["10", "20", "30"], "{}", stdout);
}

// ===== todo.md P0 #2: exhaustive audit of every f-string/`print`-family ====
// ===== format-specifier table for missing `Ty` arms ========================
//
// `Codegen::emit_print_like` (`builtins.rs`, `println`/`print`'s direct
// sole-argument path) and the general f-string-as-`str`-value path
// (`TypedExpr::FStr` in `expr.rs`) are two independently-implemented
// format-specifier tables, and each has separately shipped the identical
// bug class before: an unhandled `Ty` silently falls through to a `%p`
// catch-all, tagging whatever LLVM value it actually is (a plain `i32`
// discriminant, a packed `Color32`, a bare `u8` `PaletteIndex`, ...) as a
// vararg *pointer* -- a C-ABI vararg-slot mismatch that reads garbage bytes
// off the stack/register and prints a plausible-looking but meaningless
// value instead of crashing or erroring (`projects/snake/NOTES.md` section
// 1.5's fieldless-enum-prints-as-garbage-hex bug is the worst-known
// instance). This round's audit found the same gap for a whole new class of
// types this catch-all was never actually safe for at all: `Named`
// (struct)/`GenRef`/`Handle`/`Tuple`/`Array`/`Ring`/`Closure` all lower to
// an LLVM *aggregate* passed by value (not a pointer), so `%p` was doubly
// wrong for them -- not just an unhelpful address, an outright ABI
// mismatch (confirmed live: `println(f"point={p}")` for a two-field struct
// printed `0000000000000001` instead of failing to compile). Fixed two
// ways: `Ty::is_fstring_unprintable` types are now rejected with a clean
// diagnostic in `Checker::infer_expr`'s `Expr::FStr` arm (see
// `checks_fstring_rejects_every_unprintable_ty_variant_end_to_end` below),
// and both codegen match statements were made exhaustive (no wildcard `_`
// arm at all) so a *future* unclassified `Ty` variant fails to compile here
// rather than silently reintroducing this bug class.

/// Every `Ty` variant with a defined print/f-string format specifier,
/// paired with a source expression constructing a representative value and
/// that value's exact expected printed text. Shared by the two round-trip
/// tests below (one per format-specifier table) so both tables are checked
/// against the same expectations. Deliberately does *not* cover
/// `List`/`Map`/`Set`/`Table`/`Palette`/`Bytes`/`Ptr` (a real `i8*`, so
/// `%p`'s raw-address output can't be pinned to an exact string -- see
/// `runtime_fstring_prints_pointer_backed_types_without_crashing_end_to_end`)
/// or the seven `Ty::is_fstring_unprintable` types (rejected at check time,
/// never reach codegen at all -- see
/// `checks_fstring_rejects_every_unprintable_ty_variant_end_to_end`).
fn fstring_printable_cases() -> Vec<(&'static str, &'static str)> {
    vec![
        ("5", "5"),
        ("5 as i8", "5"),
        ("5 as i16", "5"),
        ("5 as u8", "5"),
        ("5 as u16", "5"),
        ("5 as u32", "5"),
        ("5 as i64", "5"),
        ("5 as u64", "5"),
        ("5.0", "5.000000"),
        ("5.0 as f64", "5.000000"),
        ("'a'", "a"),
        ("\"hi\"", "hi"),
        ("true", "true"),
        ("Wrapping<i32>(5)", "5"),
        ("BitField<8>(5 as u8)", "5"),
        ("Flags<Direction>(Direction::Up)", "1"),
        ("Color32(10, 20, 30, 40)", "673059850"),
        ("PaletteIndex(7)", "7"),
        ("Direction::Left", "Left"),
        ("Tick(5)", "5"),
        ("Duration(5 as i64)", "5"),
        ("Instant(5 as i64)", "5"),
        ("Symbol(\"the only symbol interned in this program\")", "0"),
        ("Fixed<32, 16>(5)", "5.000000"),
        ("Vec2(1.0, 2.0)", "Vec2(1.000000, 2.000000)"),
        ("Vec3(1.0, 2.0, 3.0)", "Vec3(1.000000, 2.000000, 3.000000)"),
        ("Vec4(1.0, 2.0, 3.0, 4.0)", "Vec4(1.000000, 2.000000, 3.000000, 4.000000)"),
        ("Quat(0.0, 0.0, 0.0, 1.0)", "Quat(0.000000, 0.000000, 0.000000, 1.000000)"),
        ("Color(1.0, 0.0, 0.0, 1.0)", "Color(1.000000, 0.000000, 0.000000, 1.000000)"),
        ("Mat2(Vec2(1.0, 0.0), Vec2(0.0, 1.0))", "Mat2(Vec2(1.000000, 0.000000), Vec2(0.000000, 1.000000))"),
        (
            "Mat3(Vec3(1.0, 0.0, 0.0), Vec3(0.0, 1.0, 0.0), Vec3(0.0, 0.0, 1.0))",
            "Mat3(Vec3(1.000000, 0.000000, 0.000000), Vec3(0.000000, 1.000000, 0.000000), Vec3(0.000000, 0.000000, 1.000000))",
        ),
        (
            "Mat4(Vec4(1.0, 0.0, 0.0, 0.0), Vec4(0.0, 1.0, 0.0, 0.0), Vec4(0.0, 0.0, 1.0, 0.0), Vec4(0.0, 0.0, 0.0, 1.0))",
            "Mat4(Vec4(1.000000, 0.000000, 0.000000, 0.000000), Vec4(0.000000, 1.000000, 0.000000, 0.000000), Vec4(0.000000, 0.000000, 1.000000, 0.000000), Vec4(0.000000, 0.000000, 0.000000, 1.000000))",
        ),
    ]
}

/// `println(f"...")`'s direct-sole-argument path -- every printable `Ty`
/// variant, exercised through `Codegen::emit_print_like`'s specifier table.
#[test]
fn runtime_fstring_prints_every_printable_ty_variant_end_to_end() {
    let cases = fstring_printable_cases();
    let mut src = String::from("enum Direction:\n    Up\n    Down\n    Left\n    Right\n\nfn main():\n");
    for (expr, _) in &cases {
        src.push_str(&format!("    println(f\"{{{}}}\")\n", expr));
    }
    let output = compile_and_run("fstring_printable_direct", &src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    let expected: Vec<&str> = cases.iter().map(|(_, out)| *out).collect();
    assert_eq!(lines, expected, "{}", stdout);
}

/// The general f-string-as-`str`-value path (assigned to a `let`, printed
/// separately) -- the same cases, exercised through the *other*
/// format-specifier table (`TypedExpr::FStr` in `expr.rs`), which is
/// implemented completely separately from `emit_print_like` and has its own
/// independent history of missing arms (see this section's header comment).
#[test]
fn runtime_fstring_value_prints_every_printable_ty_variant_end_to_end() {
    let cases = fstring_printable_cases();
    let mut src = String::from("enum Direction:\n    Up\n    Down\n    Left\n    Right\n\nfn main():\n");
    for (i, (expr, _)) in cases.iter().enumerate() {
        src.push_str(&format!("    let v{} = f\"{{{}}}\"\n    println(v{})\n", i, expr, i));
    }
    let output = compile_and_run("fstring_printable_value", &src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    let expected: Vec<&str> = cases.iter().map(|(_, out)| *out).collect();
    assert_eq!(lines, expected, "{}", stdout);
}

/// The seven pointer-backed types (`List`/`Map`/`Set`/`Table`/`Palette`/
/// `Bytes`/`Ptr`, every one a bare `i8*`) all deliberately keep the `%p`
/// address-print behavior (see the arm's doc comment in both
/// `emit_print_like` and `TypedExpr::FStr`) -- there's no per-element/
/// per-field pretty-printer, so this only asserts the program compiles,
/// runs, and produces one non-empty line per value, not any particular
/// address text.
#[test]
fn runtime_fstring_prints_pointer_backed_types_without_crashing_end_to_end() {
    let src = "struct Enemy:\n    hp: i32\n\nfn main():\n    \
               let lst: List<i32> = List<i32>()\n    println(f\"{lst}\")\n    \
               let mp: Map<i32, i32> = Map<i32, i32>()\n    println(f\"{mp}\")\n    \
               let st: Set<i32> = Set<i32>()\n    println(f\"{st}\")\n    \
               let tbl: Table<Enemy> = Table<Enemy>()\n    println(f\"{tbl}\")\n    \
               let pal: Palette = Palette()\n    println(f\"{pal}\")\n    \
               let by: Bytes = Bytes()\n    println(f\"{by}\")\n    \
               let p: ptr = null_ptr()\n    println(f\"{p}\")\n";
    let output = compile_and_run("fstring_pointer_backed_no_crash", src);
    assert!(output.status.success(), "{:?}", output.status);
    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().collect();
    assert_eq!(lines.len(), 7, "one line per pointer-backed value: {}", stdout);
    assert!(lines.iter().all(|l| !l.trim().is_empty()), "every line should have printed something: {}", stdout);
}

/// The seven `Ty::is_fstring_unprintable` types (`Named`/struct, `GenRef`,
/// `Handle`, `Tuple`, `Array`, `Ring`, `Closure`) all lower to an LLVM
/// aggregate passed *by value* -- interpolating one used to silently
/// compile down to a vararg `%p` pointer tag on a non-pointer register (a
/// C-ABI mismatch, confirmed live: a two-`i32`-field struct printed
/// `0000000000000001` instead of its actual field values or a diagnostic).
/// Now a clean `Checker` diagnostic instead, for every one of the seven.
#[test]
fn checks_fstring_rejects_every_unprintable_ty_variant_end_to_end() {
    let src = "struct Point:\n    x: i32\n    y: i32\n\narena Points: Point\n\nfn main():\n    \
               spawn Points(1, 2)\n    \
               let p = Point(1, 2)\n    println(f\"{p}\")\n    \
               let t = (1, 2)\n    println(f\"{t}\")\n    \
               let arr: [i32; 3] = [1; 3]\n    println(f\"{arr}\")\n    \
               let r = GenRef<Point>(0)\n    println(f\"{r}\")\n    \
               let h = Handle<Point>(0)\n    println(f\"{h}\")\n    \
               let c = fn(x: i32) -> i32:\n        x\n    println(f\"{c}\")\n    \
               let ring = Ring<i32, 4>()\n    println(f\"{ring}\")\n";
    let module = Driver::parse(src).expect("should parse");
    let Err(diags) = Driver::check(&module) else { panic!("f-string interpolation of every unprintable type should fail to type-check") };
    let messages: Vec<&str> = diags.iter().map(|d| d.message.as_str()).collect();
    assert_eq!(diags.len(), 7, "one diagnostic per unprintable value, none silently accepted: {:?}", messages);
    for needle in ["Named", "Tuple", "Array", "GenRef", "Handle", "Closure", "Ring"] {
        assert!(
            messages.iter().any(|m| m.contains("cannot interpolate") && m.contains(needle)),
            "expected a 'cannot interpolate' diagnostic naming {}: {:?}", needle, messages
        );
    }
}

// ===== Audio playback / gamepad input (`todo.md` #8 "Audio playback and ===
// ===== gamepad input"): `sound_load`/`sound_free`/`sound_play`/          ===
// ===== `music_play`/`music_stop`/`sound_stop_all` (`crate::codegen::audio`) =
// ===== and `gamepad_count`/`gamepad_open`/`gamepad_close`/                ===
// ===== `gamepad_button_down`/`gamepad_axis`/`gamepad_attached`            ===
// ===== (`crate::codegen::gamepad`). ========================================

/// Absolute path (forward-slashed, so it drops cleanly into a Star string
/// literal with no backslash-escaping) to the committed short WAV clip
/// (`examples/assets/beep.wav`: 0.25s, 44100Hz, stereo, 16-bit PCM, the
/// canonical shape `sound_load` accepts) used by every "real file" audio
/// test below.
fn beep_wav_path() -> String {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("examples")
        .join("assets")
        .join("beep.wav")
        .to_string_lossy()
        .replace('\\', "/")
}

/// Hand-build a canonical 44-byte-header PCM WAV file's bytes with
/// arbitrary format fields -- lets tests probe `sound_load`'s validation
/// (wrong sample rate/bit depth/channel count) without needing a whole
/// zoo of committed asset files, mirroring this module's own hand-rolled
/// WAV parser (`crate::codegen::audio::emit_sound_load`) byte-for-byte.
fn build_wav_bytes(sample_rate: u32, channels: u16, bits_per_sample: u16, num_frames: u32) -> Vec<u8> {
    let block_align = channels as u32 * (bits_per_sample as u32 / 8);
    let data_size = num_frames * block_align;
    let byte_rate = sample_rate * block_align;
    let mut buf = Vec::new();
    buf.extend_from_slice(b"RIFF");
    buf.extend_from_slice(&(36 + data_size).to_le_bytes());
    buf.extend_from_slice(b"WAVE");
    buf.extend_from_slice(b"fmt ");
    buf.extend_from_slice(&16u32.to_le_bytes());
    buf.extend_from_slice(&1u16.to_le_bytes()); // PCM
    buf.extend_from_slice(&channels.to_le_bytes());
    buf.extend_from_slice(&sample_rate.to_le_bytes());
    buf.extend_from_slice(&byte_rate.to_le_bytes());
    buf.extend_from_slice(&(block_align as u16).to_le_bytes());
    buf.extend_from_slice(&bits_per_sample.to_le_bytes());
    buf.extend_from_slice(b"data");
    buf.extend_from_slice(&data_size.to_le_bytes());
    buf.resize(buf.len() + data_size as usize, 0);
    buf
}

/// Write `bytes` to a fresh file under a unique scratch directory (so
/// concurrently-running tests never collide on the same path), returning
/// its forward-slashed path. The caller is responsible for nothing further
/// -- these are one-shot per-test scratch files in the OS temp dir, never
/// cleaned up individually, matching this file's existing scratch-file
/// tests (e.g. `file_open`'s own temp-path helpers).
fn write_scratch_file(name: &str, bytes: &[u8]) -> String {
    let dir = std::env::temp_dir().join("star_test_audio_assets");
    std::fs::create_dir_all(&dir).expect("failed to create scratch dir");
    let path = dir.join(name);
    std::fs::write(&path, bytes).expect("failed to write scratch file");
    path.to_string_lossy().replace('\\', "/")
}

